func TestLeaseStoreDistinctStickyKeysCanCoexistConcurrently(t *testing.T) {
	store := NewLeaseStore()
	now := time.Date(2026, 5, 2, 10, 0, 0, 0, time.UTC)
	var wg sync.WaitGroup
	for i := 0; i < 32; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			key := NormalizeLeaseKey(string(rune('a' + i)))
			endpoint := "desk-a"
			if i%2 == 1 {
				endpoint = "desk-b"
			}
			store.Acquire(now.Add(time.Duration(i)*time.Second), time.Minute, key, "agent", endpoint, "model-a")
		}(i)
	}
	wg.Wait()

	leases := store.LiveByScope(now.Add(30*time.Second), "agent", "model-a")
	if len(leases) != 32 {
