	}
	counts := store.LeaseCounts(now.Add(30*time.Second), "agent", "model-a")
	if counts["desk-a"] == 0 || counts["desk-b"] == 0 {
		t.Fatalf("counts=%#v, want both endpoints represented", counts)
	}
}

