// TestRouteStatus_emptyConfig verifies that RouteStatus returns an empty report
// when no ServiceConfig is provided.
func TestRouteStatus_emptyConfig(t *testing.T) {
	svc := newTestService(t, ServiceOptions{})
	report, err := svc.RouteStatus(context.Background())
	if err != nil {
		t.Fatalf("RouteStatus: unexpected error: %v", err)
	}
	if report == nil {
		t.Fatal("expected non-nil report")
	}
	if len(report.Routes) != 0 {
		t.Errorf("Routes: got %d, want 0", len(report.Routes))
	}
	if report.GeneratedAt.IsZero() {
		t.Error("GeneratedAt should be set")
	}
}

// TestRouteStatus_modelsPopulatedFromProviders verifies RouteStatus reports
// live provider/model candidates, not configured route tables.
func TestRouteStatus_modelsPopulatedFromProviders(t *testing.T) {
	sc := &fakeServiceConfig{
		providers: map[string]ServiceProviderEntry{
			"bragi":      {Type: "lmstudio", BaseURL: "http://bragi.invalid/v1", Model: "qwen3-27b"},
			"openrouter": {Type: "openrouter", BaseURL: "https://openrouter.invalid/v1", Model: "qwen3-27b"},
		},
		names: []string{"bragi", "openrouter"},
	}
	svc := newTestService(t, ServiceOptions{ServiceConfig: sc})

	report, err := svc.RouteStatus(context.Background())
	if err != nil {
		t.Fatalf("RouteStatus: %v", err)
	}
	if len(report.Routes) != 1 {
		t.Fatalf("Routes: got %d, want 1", len(report.Routes))
	}

	entry := report.Routes[0]
	if entry.Model != "qwen3-27b" {
		t.Errorf("Model: got %q, want %q", entry.Model, "qwen3-27b")
	}
	if entry.Strategy != "auto" {
		t.Errorf("Strategy: got %q, want auto", entry.Strategy)
	}
	if len(entry.Candidates) != 2 {
		t.Fatalf("Candidates: got %d, want 2", len(entry.Candidates))
	}
	if entry.Candidates[0].Provider != "bragi" {
		t.Errorf("Candidates[0].Provider: got %q, want %q", entry.Candidates[0].Provider, "bragi")
	}
	if entry.Candidates[0].ServerInstance == "" {
		t.Errorf("Candidates[0].ServerInstance should be populated: %#v", entry.Candidates[0])
	}
	if entry.Candidates[1].Provider != "openrouter" {
		t.Errorf("Candidates[1].Provider: got %q, want %q", entry.Candidates[1].Provider, "openrouter")
	}
	// No cooldowns set — both should be healthy.
	for i, c := range entry.Candidates {
		if !c.Healthy {
			t.Errorf("Candidates[%d].Healthy: got false, want true", i)
		}
		if c.Cooldown != nil {
			t.Errorf("Candidates[%d].Cooldown: expected nil", i)
		}
	}
}

// TestRouteStatus_lastDecisionCached verifies that calling ResolveRoute and
// then RouteStatus surfaces the cached LastDecision on the matching entry.
func TestRouteStatus_lastDecisionCached(t *testing.T) {
	// Build a minimal ServiceConfig that satisfies the routing engine.
	sc := &fakeServiceConfig{
		providers: map[string]ServiceProviderEntry{
			"bragi": {Type: "lmstudio", BaseURL: "http://127.0.0.1:9999/v1", Model: "qwen3-27b"},
		},
		names:       []string{"bragi"},
		defaultName: "bragi",
	}

	// Seed registry with the "fiz" harness available so routing can resolve.
	reg := harnesses.NewRegistry()
	svc := &service{
		opts:     ServiceOptions{ServiceConfig: sc},
		registry: reg,
	}

	// Inject a decision directly into the cache (simulating a resolved route)
	// since ResolveRoute may fail without a real provider.
	dec := &RouteDecision{
		Harness:        "fiz",
		Provider:       "bragi",
		Endpoint:       "desk-a",
		ServerInstance: "desk-a",
		Model:          "qwen3-27b",
		Reason:         "test",
		Sticky:         RouteStickyState{KeyPresent: true, Assignment: "reused", ServerInstance: "desk-a", Reason: "live sticky lease reused"},
	}
	svc.cacheRouteDecision("qwen3-27b", dec)

	report, err := svc.RouteStatus(context.Background())
	if err != nil {
		t.Fatalf("RouteStatus: %v", err)
	}
	if len(report.Routes) != 1 {
		t.Fatalf("Routes: got %d, want 1", len(report.Routes))
	}
	entry := report.Routes[0]
	if entry.LastDecision == nil {
		t.Fatal("LastDecision: expected non-nil after ResolveRoute")
	}
	if entry.LastDecision.Provider != "bragi" {
		t.Errorf("LastDecision.Provider: got %q, want %q", entry.LastDecision.Provider, "bragi")
	}
	if entry.LastDecision.ServerInstance == "" {
		t.Errorf("LastDecision.ServerInstance should be populated: %#v", entry.LastDecision)
	}
	if entry.LastDecision.Model != "qwen3-27b" {
		t.Errorf("LastDecision.Model: got %q, want %q", entry.LastDecision.Model, "qwen3-27b")
	}
	if entry.LastDecisionAt.IsZero() {
		t.Error("LastDecisionAt: should be non-zero")
	}
	if entry.SelectedEndpoint != "desk-a" {
		t.Fatalf("SelectedEndpoint = %q, want desk-a", entry.SelectedEndpoint)
	}
	if entry.SelectedServerInstance == "" {
		t.Fatalf("SelectedServerInstance should be populated: %#v", entry)
	}
	if !entry.Sticky.KeyPresent || entry.Sticky.Assignment != "reused" {
		t.Fatalf("Sticky = %#v, want reused sticky evidence", entry.Sticky)
	}
}

// TestRouteStatus_lastDecisionCached_viaResolveRoute verifies the full path:
// ResolveRoute → cache write → RouteStatus reads cache.
func TestRouteStatus_lastDecisionCached_viaResolveRoute(t *testing.T) {
	// We need the routing engine to actually resolve. The engine picks
	// harnesses from the registry. "fiz" is always in the registry.
	// We give it a provider so the engine can build a candidate.
	sc := &fakeServiceConfig{
		providers: map[string]ServiceProviderEntry{
			"bragi": {Type: "lmstudio", BaseURL: "http://127.0.0.1:9999/v1", ServerInstance: "bragi-instance", Model: "mymodel"},
		},
		names:       []string{"bragi"},
		defaultName: "bragi",
	}

	svc := &service{
		opts:     ServiceOptions{ServiceConfig: sc},
		registry: harnesses.NewRegistry(),
	}

	// ResolveRoute with model="mymodel". The engine resolves against the
	// "fiz" harness + bragi provider.
	dec, err := svc.ResolveRoute(context.Background(), RouteRequest{
		Model:    "mymodel",
		Provider: "bragi",
	})
	if err != nil {
		// Routing may return an error if the engine can't fully resolve;
		// skip in that case — the direct-cache test covers the cache logic.
		t.Skipf("ResolveRoute returned error (provider not live): %v", err)
	}
	if dec == nil {
		t.Fatal("RouteDecision: nil")
	}

	report, err := svc.RouteStatus(context.Background())
	if err != nil {
		t.Fatalf("RouteStatus: %v", err)
	}
	var found *RouteStatusEntry
	for i := range report.Routes {
		if report.Routes[i].Model == "mymodel" {
			found = &report.Routes[i]
			break
		}
	}
	if found == nil {
		t.Fatal("route 'mymodel' not found in report")
	}
	if found.LastDecision == nil {
		t.Fatal("LastDecision: expected non-nil after successful ResolveRoute")
	}
	if dec.Endpoint != "" && found.SelectedEndpoint != dec.Endpoint {
		t.Fatalf("SelectedEndpoint = %q, want %q", found.SelectedEndpoint, dec.Endpoint)
	}
}

func TestRouteStatus_attemptCooldownStateSurfaces(t *testing.T) {
	sc := &fakeServiceConfig{
		healthCooldown: 30 * time.Second,
		providers: map[string]ServiceProviderEntry{
			"bragi":      {Type: "lmstudio", BaseURL: "http://bragi.invalid/v1", Model: "qwen3-27b"},
			"openrouter": {Type: "openrouter", BaseURL: "https://openrouter.invalid/v1", Model: "qwen3-27b"},
		},
		names: []string{"bragi", "openrouter"},
	}
	svc := newTestService(t, ServiceOptions{ServiceConfig: sc})
	recordedAt := time.Now().Add(-time.Second).UTC()
	if err := svc.RecordRouteAttempt(context.Background(), RouteAttempt{
		Harness:   "fiz",
		Provider:  "bragi",
		Model:     "qwen3-27b",
		Status:    "failed",
		Reason:    "rate_limit",
		Timestamp: recordedAt,
	}); err != nil {
		t.Fatalf("RecordRouteAttempt: %v", err)
	}

	report, err := svc.RouteStatus(context.Background())
	if err != nil {
		t.Fatalf("RouteStatus: %v", err)
	}
	if len(report.Routes) != 1 {
		t.Fatalf("Routes: got %d, want 1", len(report.Routes))
	}

	entry := report.Routes[0]
	if len(entry.Candidates) != 2 {
		t.Fatalf("Candidates: got %d, want 2", len(entry.Candidates))
	}

	// Find bragi and openrouter candidates.
	byProvider := make(map[string]RouteCandidateStatus, 2)
	for _, c := range entry.Candidates {
		byProvider[c.Provider] = c
	}

	bragi, ok := byProvider["bragi"]
	if !ok {
		t.Fatal("bragi candidate not found")
	}
	if bragi.Healthy {
		t.Error("bragi: Healthy should be false (in cooldown)")
	}
	if bragi.Cooldown == nil {
		t.Fatal("bragi: Cooldown should be non-nil")
	}
	if bragi.Cooldown.Reason != "rate_limit" {
		t.Errorf("bragi Cooldown.Reason: got %q, want %q", bragi.Cooldown.Reason, "rate_limit")
	}
	if bragi.Cooldown.Until.IsZero() {
		t.Error("bragi Cooldown.Until should be non-zero")
	}

package fizeau

import (
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

const stickyRouteLeaseTTL = routehealth.DefaultLeaseTTL
const stickyRouteAffinityBonus = 250.0

func (s *service) routeLeaseStore() *routehealth.LeaseStore {
	if s.routeLeases == nil {
		s.routeLeases = routehealth.NewLeaseStore()
	}
	return s.routeLeases
}

func (s *service) routeUtilizationStore() *routehealth.UtilizationStore {
	if s.routeUtilization == nil {
		s.routeUtilization = routehealth.NewUtilizationStore()
	}
	return s.routeUtilization
}

func (s *service) applyStickyRouteLease(stickyKey string, decision *RouteDecision) {
	if s == nil || decision == nil || strings.TrimSpace(stickyKey) == "" {
		return
	}
	decision.Sticky.KeyPresent = true
	if decision.Harness != "fiz" || decision.Provider == "" {
		decision.Sticky.Assignment = "not_applicable"
		return
	}

	now := time.Now().UTC()
	store := s.routeLeaseStore()
	baseProvider, _, _ := splitEndpointProviderRef(decision.Provider)
	if baseProvider == "" {
		baseProvider = decision.Provider
	}
	if baseProvider == "" || decision.Model == "" {
		return
	}

	key := routehealth.NormalizeLeaseKey(stickyKey)
	selectedServerInstance := strings.TrimSpace(decision.ServerInstance)
	if selectedServerInstance == "" {
		selectedServerInstance = strings.TrimSpace(decision.Endpoint)
	}
	if selectedServerInstance == "" {
		_, selectedServerInstance, _ = splitEndpointProviderRef(decision.Provider)
	}
	if selectedServerInstance == "" {
		selectedServerInstance = decision.Provider
	}
	lease, ok := store.Live(now, key)
	if ok && lease.Endpoint == selectedServerInstance {
		decision.Sticky.Assignment = "reused"
		decision.Sticky.ServerInstance = selectedServerInstance
		decision.Sticky.Bonus = stickyRouteAffinityBonus
		decision.Sticky.Reason = "live sticky lease reused"
	} else if ok {
		decision.Sticky.Assignment = "moved"
		decision.Sticky.ServerInstance = selectedServerInstance
		decision.Sticky.Bonus = 0
		decision.Sticky.Reason = "sticky server instance lost to a stronger candidate"
	} else {
		decision.Sticky.Assignment = "acquired"
		decision.Sticky.ServerInstance = selectedServerInstance
		decision.Sticky.Bonus = 0
		if decision.Sticky.Reason == "" {
			decision.Sticky.Reason = "new sticky lease acquired"
		}
	}
	if selectedServerInstance == "" {
		decision.Sticky.Assignment = "none"
		return
	}
	store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, selectedServerInstance, decision.Model)
}

func (s *service) routeEndpointLoadsResolver(now time.Time) func(provider, endpoint, model string) (routing.EndpointLoad, bool) {
	if s == nil {
		return nil
	}
	leaseStore := s.routeLeaseStore()
	utilStore := s.routeUtilizationStore()
	return func(provider, endpoint, model string) (routing.EndpointLoad, bool) {
		leaseCounts := leaseStore.LeaseCounts(now, provider, model)
		loads := utilStore.EndpointLoads(provider, model, leaseCounts)
		load, ok := loads[endpoint]
		if !ok {
			if count, ok := leaseCounts[endpoint]; ok {
				return routing.EndpointLoad{
					LeaseCount:       count,
					NormalizedLoad:   float64(count),
					UtilizationFresh: false,
				}, true
			}
			return routing.EndpointLoad{}, false
		}
		return routing.EndpointLoad{
			LeaseCount:           load.LeaseCount,
			NormalizedLoad:       load.NormalizedLoad,
			UtilizationFresh:     load.UtilizationFresh,
			UtilizationSaturated: load.UtilizationSaturated,
		}, true
	}
}

func (s *service) routeStickyServerInstanceResolver(now time.Time) func(stickyKey string) (string, bool) {
	if s == nil {
		return nil
	}
	store := s.routeLeaseStore()
	return func(stickyKey string) (string, bool) {
		if strings.TrimSpace(stickyKey) == "" {
			return "", false
		}
		lease, ok := store.Live(now, routehealth.NormalizeLeaseKey(stickyKey))
		if !ok {
			return "", false
		}
		if lease.Endpoint == "" {
			return "", false
		}
		return lease.Endpoint, true
	}
}

